python3 -c "
import csv
rows=[]
with open('eu_economic_data.csv') as f:
    for r in csv.DictReader(f):
        for k in r:
            if k not in ('Country','Year'): r[k]=float(r[k])
        r['Year']=int(r['Year']); rows.append(r)
bc={}
for r in rows: bc.setdefault(r['Country'],[]).append(r)
print('EU 2022-24:')
for r in bc['EU_Total']: print(r['Year'],'growth',r['GDP_Growth_Pct'],'infl',r['Inflation_Pct'],'unemp',r['Unemployment_Pct'],'trade',r['Trade_Balance_Billion_EUR'],'debt',r['Public_Debt_Pct_GDP'])
print()
for c,rs in bc.items():
    if c=='EU_Total': continue
    d={r['Year']:r for r in rs}
    print(f\"{c:12s} g22={d[2022]['GDP_Growth_Pct']:4.1f} g24={d[2024]['GDP_Growth_Pct']:4.1f} u22={d[2022]['Unemployment_Pct']:4.1f} u24={d[2024]['Unemployment_Pct']:4.1f} debt24={d[2024]['Public_Debt_Pct_GDP']:5.1f} trade24={d[2024]['Trade_Balance_Billion_EUR']:6.1f}\")
"

